(()=>{
  const tests = document.getElementById('tests').innerText;
  const vf = document.getElementById('verdictForce').innerText;
  const vs = document.getElementById('verdictStress').innerText;
  const metrics = {
    kdeg: document.getElementById('r_kdeg').innerText,
    C: document.getElementById('r_C').innerText,
    M: document.getElementById('r_M').innerText,
    F: document.getElementById('r_F').innerText,
    sigma: document.getElementById('r_sigma').innerText,
    sf: document.getElementById('r_sf').innerText,
  };
  return JSON.stringify({metrics, vf, vs, tests}, null, 1);
})()

(()=>{
  const html = document.getElementById('tests').innerHTML;
  const fails = (html.match(/❌/g)||[]).length;
  const passes = (html.match(/✅/g)||[]).length;
  const overall = html.includes('PASS') ? 'PASS' : (html.includes('FAIL')?'FAIL':'?');
  return JSON.stringify({overall, passes, fails});
})()

