(()=>{
  const click=(mode)=>{[...document.querySelectorAll('#doormode button')].find(b=>b.dataset.mode===mode).click();};
  const snap=()=>({
    target: document.getElementById('target').value,
    big: document.getElementById('bigForce').innerText.replace(/\n/g,' | '),
    need: document.getElementById('barNeedVal').innerText,
    spring: document.getElementById('barSpringVal').innerText,
  });
  const out={};
  out.initial = snap();           // 기본 = 소형
  click('medium'); out.medium = snap();
  click('large');  out.large = snap();
  click('small');  out.small = snap();
  // 직접 입력
  const t=document.getElementById('target'); t.value='4'; t.dispatchEvent(new Event('input',{bubbles:true}));
