// 도어에 필요한 힘 → 토크 환산
let M_req = null, F_req = null;
const tv = parseFloat($("target").value);
if (!isNaN(tv) && L > 0) { F_req = tv; M_req = tv * L; }

// ---- 큰 결과 (쉬운 말) ----
const big = $("bigForce");
if (!r) {
  big.className = "big-result warn";
