} else if (M_req != null && M_req > 0) {
  const ratio = r.M / M_req;
  const doorName = DOORS[doorMode] ? DOORS[doorMode].name + " 도어" : "도어";
  if (ratio >= 1.15) {
    big.className = "big-result good";
    big.innerHTML = `<div class="emoji">🎉</div><div class="headline">좋아요! ${doorName}를 잘 밀어내요</div>
