    big.className = "big-result warn";
    big.innerHTML = `<div class="emoji">😅</div><div class="headline">아슬아슬하게 돼요</div>
      <div class="detail">힘이 딱 맞아요. 조금만 더 세면 안심이에요. (철사를 살짝 굵게!)</div>`;
