  $("barNeed").style.width = Math.min(100, F_req / maxF * 100) + "%";
  $("barNeedVal").textContent = fmt(F_req, 1) + " N";
} else {
  $("barNeed").style.width = "0%";
  $("barNeedVal").textContent = "안 정함";
}

