  big.className = "big-result good";
  big.innerHTML = `<div class="emoji">🎉</div><div class="headline">어느 방향이든 도어를 잘 밀어내요!</div>
    <div class="detail">내 스프링 힘 <b>${fmt(r.F,1)} N</b> — 눕혀서도 세워서도 충분해요.</div>`;
} else if (pass_v) {
  big.className = "big-result warn";
  big.innerHTML = `<div class="emoji">😅</div><div class="headline">세워서 쓰면 OK, 눕히면 약해요</div>
