(()=>{
  const setv=(id,v)=>{const e=document.getElementById(id);e.value=v;e.dispatchEvent(new Event('input',{bubbles:true}));};
  const snap=()=>({
    big: document.getElementById('bigForce').innerText.replace(/\n/g,' | '),
    spring: document.getElementById('barSpringVal').innerText,
    needH: document.getElementById('needHName').innerText + ' = ' + document.getElementById('barNeedHVal').innerText,
    needV: document.getElementById('needVName').innerText + ' = ' + document.getElementById('barNeedVVal').innerText,
  });
  const out={};
  out.default = snap();  // 40x30x10, 15g, 스프링 d1/D10/n5
  // 무거운 큰 도어
  setv('dw','120'); setv('dd','80'); setv('dh','15'); setv('dweight','300');
  out.heavy = snap();
  // 무게 비움
  setv('dweight','0');
  out.noweight = snap();
  // 손계산 확인: 기본값 검산
  setv('dw','40'); setv('dd','30'); setv('dh','10'); setv('dweight','15');
  // arm=max(40,30,10)/2=20mm, W=0.015*9.80665=0.14710N, Mgrav=2.9421 N*mm, Mfric=0.8826
  // L=20 -> F_req_h=0.1471N, F_req_v=0.0441N. spring M=95.83 -> pass both
  out.check = {
    expect_Mgrav: 2.9421, expect_FreqH: 0.1471, expect_FreqV: 0.0441
  };
  out.testPass = document.getElementById('tests').innerHTML.includes('PASS');
  out.buttonWord = (document.body.innerText.match(/버튼/g)||[]).length;
  return JSON.stringify(out,null,1);
})()

