input.command:
$gh = Get-Command gh -ErrorAction SilentlyContinue; if ($gh) { "gh FOUND: $($gh.Source)"; gh auth status } else { "gh NOT FOUND" }
"--- token env ---"
if ($env:GITHUB_TOKEN) { "GITHUB_TOKEN set" } else { "no GITHUB_TOKEN" }
if ($env:GH_TOKEN) { "GH_TOKEN set" } else { "no GH_TOKEN" }
"--- git identity ---"
git config user.name; git config user.email

$gh = "C:\Program Files\GitHub CLI\gh.exe"
$url = "https://mungbws1031.github.io/torsion-spring-simulator/"
$status = ""
for ($i=0; $i -lt 12; $i++) {
  $b = & $gh api "repos/mungbws1031/torsion-spring-simulator/pages/builds/latest" --jq ".status" 2>$null
  if ($b -eq "built") { $status = "built"; break }
  Start-Sleep -Seconds 10
}
"build status: $(if($status){'built'}else{'still building'})"
try {
  $r = Invoke-WebRequest -Uri $url -UseBasicParsing -TimeoutSec 15
  "HTTP $($r.StatusCode) — page length $($r.Content.Length) chars"
  if ($r.Content -match '토션스프링|스프링 실험실') { "✅ 시뮬레이터 페이지 정상 로드 확인" } else { "page loaded but title text not matched" }
} catch { "page not reachable yet: $($_.Exception.Message)" }

