227	        <div class="metric"><div class="k">각 강성</div><div class="v"><span id="r_kdeg">–</span> <span class="u">N·mm/도</span></div></div>
228	        <div class="metric"><div class="k">스프링 지수 C = D/d</div><div class="v"><span id="r_C">–</span></div></div>
229	        <div class="metric"><div class="k">토크 @θ</div><div class="v"><span id="r_M">–</span> <span class="u">N·mm</span></div></div>
230	        <div class="metric"><div class="k">다리 끝 힘 @θ</div><div class="v"><span id="r_F">–</span> <span class="u">N</span></div></div>
231	        <div class="metric"><div class="k">굽힘응력 σ</div><div class="v"><span id="r_sigma">–</span> <span class="u">MPa</span></div></div>
232	        <div class="metric"><div class="k">허용응력 / 안전율</div><div class="v"><span id="r_sf">–</span> <span class="u">SF</span></div></div>
233	      </div>
234	      <div class="chart-wrap"><svg id="chart" viewBox="0 0 520 280"></svg></div>
235	      <div style="margin-top:10px">
236	        <b>자가 테스트 (공식 검산)</b>
237	        <div id="tests" style="margin-top:6px"></div>
238	      </div>
239	    </details>
240	  </div>
241	</div>
242	
243	<script>
244	// ===================== 재질 데이터 (계산용 — 변경 없음) =====================
245	const MATERIALS = {
246	  music:   { name: "🎹 피아노 줄 (가장 튼튼·음악선)", E: 207000, A: 2211, m: 0.145, allowFrac: 0.80 },
247	  chromesi:{ name: "크롬실리콘 (아주 튼튼)",          E: 207000, A: 2005, m: 0.168, allowFrac: 0.85 },
248	  chromev: { name: "크롬바나듐 (튼튼)",               E: 207000, A: 1909, m: 0.168, allowFrac: 0.85 },
249	  oiltemp: { name: "오일템퍼선 (보통)",               E: 207000, A: 1855, m: 0.187, allowFrac: 0.85 },
250	  sts:     { name: "스테인리스 (녹 안 슬어요)",       E: 193000, A: 1867, m: 0.146, allowFrac: 0.80 },
251	  harddrawn:{ name: "그냥 철사 (가장 약함·경강선)",   E: 207000, A: 1783, m: 0.190, allowFrac: 0.80 },
252	  custom:  { name: "내가 직접 정하기",                E: 207000, A: null, m: null, allowFrac: 0.80 },
253	};
254	
255	// ===================== 핵심 계산 (순수 함수 — 변경 없음) =====================
256	function computeSpring(p) {
257	  const { E, d, D, n, L, thetaDeg } = p;
258	  const C = D / d;
259	  const kTurn = (E * Math.pow(d, 4)) / (10.8 * D * n);
260	  const kDeg = kTurn / 360;
261	  const M = kDeg * thetaDeg;
262	  const F = L > 0 ? M / L : 0;
263	  const Ki = (4 * C * C - C - 1) / (4 * C * (C - 1));
264	  const sigma = Ki * 32 * M / (Math.PI * Math.pow(d, 3));
265	  let Sut = p.Sut, sigmaAllow = null, SF = null;
266	  if (Sut && Sut > 0) {
267	    sigmaAllow = p.allowFrac * Sut;
268	    SF = sigma > 0 ? sigmaAllow / sigma : Infinity;
269	  }
270	  return { C, kTurn, kDeg, M, F, Ki, sigma, Sut, sigmaAllow, SF };
271	}
272	function tensileStrength(A, m, d) {
273	  if (A == null || m == null) return null;
274	  return A * Math.pow(d, -m);
275	}
276	
277	// ===================== 도어 물리 상수 =====================
278	const G = 9.80665;        // 중력가속도 (m/s²)
279	const FRICTION_FRAC = 0.30; // 세워서 쓸 때: 무게 토크의 30%만 마찰로 가정
280	
281	// ===================== UI 상태 =====================
282	let diaMode = "mean";
283	const $ = (id) => document.getElementById(id);
284	
285	function populateMaterials() {
286	  const sel = $("material");
287	  Object.entries(MATERIALS).forEach(([k, v]) => {
288	    const o = document.createElement("option");
289	    o.value = k; o.textContent = v.name;
290	    sel.appendChild(o);
291	  });
292	  sel.value = "music";
293	}
294	function currentMeanD(d) {
295	  const v = parseFloat($("diaInput").value) || 0;
296	  if (diaMode === "od") return v - d;
297	  if (diaMode === "id") return v + d;
298	  return v;
299	}
300	function applyMaterial() {
301	  const mat = MATERIALS[$("material").value];
302	  const d = parseFloat($("d").value) || 1;
303	  $("E").value = mat.E;
304	  const sut = tensileStrength(mat.A, mat.m, d);
305	  $("Sut").value = sut ? Math.round(sut) : "";
306	}
307	function fmt(x, dp = 2) {
308	  if (x === Infinity) return "∞";
309	  if (!isFinite(x)) return "–";
310	  return Number(x).toLocaleString("en-US", { maximumFractionDigits: dp, minimumFractionDigits: dp });
311	}
312	
313	// 힘(N) → 친숙한 무게 비유
314	function weightAnalogy(N) {
315	  const g = N / 9.80665 * 1000; // 그램
316	  let obj;
317	  if (g < 30) obj = "동전 몇 개 🪙";
318	  else if (g < 80) obj = "달걀 1개 🥚";
319	  else if (g < 180) obj = "달걀 2~3개 🥚";
320	  else if (g < 350) obj = "사과 1개 🍎";
321	  else if (g < 700) obj = "물병(500mL) 한 통 💧";
322	  else if (g < 1500) obj = "책 한 권 📕";
323	  else if (g < 3500) obj = "물 2L 한 통 🍶";
324	  else obj = "아주 무거워요 🏋️";
325	  const gStr = g >= 1000 ? (g/1000).toFixed(1) + "kg" : Math.round(g) + "g";
326	  return `약 ${gStr} (${obj})`;
327	}
328	
329	// ===================== 렌더 =====================
330	function render() {
331	  const mat = MATERIALS[$("material").value];
332	  const d = parseFloat($("d").value) || 0;
333	  const D = currentMeanD(d);
334	  const n = parseFloat($("n").value) || 0;
335	  const L = parseFloat($("L").value) || 0;
336	  const thetaDeg = parseFloat($("theta").value) || 0;
337	  const E = parseFloat($("E").value) || 0;
338	  const Sut = parseFloat($("Sut").value) || null;
339	
340	  const valid = d > 0 && D > d && n > 0 && E > 0;
341	  const r = valid ? computeSpring({ E, d, D, n, L, thetaDeg, Sut, allowFrac: mat.allowFrac }) : null;
342	
343	  // 어른용 숫자
344	  $("r_kdeg").textContent  = r ? fmt(r.kDeg, 3) : "–";
345	  $("r_C").textContent     = r ? fmt(r.C, 2) : "–";
346	  $("r_M").textContent     = r ? fmt(r.M, 1) : "–";
347	  $("r_F").textContent     = r ? fmt(r.F, 2) : "–";
348	  $("r_sigma").textContent = r ? fmt(r.sigma, 0) : "–";
349	  $("r_sf").textContent    = r && r.SF != null ? fmt(r.SF, 2) : "–";
350	
351	  // ---- 도어 크기·무게로 필요한 힘 계산 ----
352	  const dwid = parseFloat($("dw").value) || 0;
353	  const ddep = parseFloat($("dd").value) || 0;
354	  const dhei = parseFloat($("dh").value) || 0;
355	  const weightG = parseFloat($("dweight").value) || 0;
356	  const armDoor = Math.max(dwid, ddep, dhei) / 2;        // 무게중심까지 거리 (mm)
357	  const Wforce  = weightG / 1000 * G;                    // 도어 무게 힘 (N)
358	  const M_grav  = Wforce * armDoor;                      // 🛏️ 눕혀서: 무게 들기 토크 (N·mm)
359	  const M_fric  = FRICTION_FRAC * M_grav;                // 🧍 세워서: 마찰만 (무게의 30% 가정)
360	  const haveDoor = weightG > 0 && armDoor > 0 && L > 0;
361	  const F_req_h = haveDoor ? M_grav / L : null;          // 비교용 힘 (N, 스프링 팔 기준)
362	  const F_req_v = haveDoor ? M_fric / L : null;
363	  const pass_h = (r && haveDoor) ? r.M >= M_grav : null;
364	  const pass_v = (r && haveDoor) ? r.M >= M_fric : null;
365	
366	  // ---- 큰 결과 (쉬운 말) ----
367	  const big = $("bigForce");
368	  if (!r) {
369	    big.className = "big-result warn";
370	    big.innerHTML = `<div class="emoji">🤔</div><div class="headline">값을 채워 주세요</div>
371	      <div class="detail">철사 굵기·동그라미 크기·바퀴 수를 넣으면 실험이 시작돼요!</div>`;
372	  } else if (!haveDoor) {
373	    big.className = "big-result good";
374	    big.innerHTML = `<div class="emoji">💙</div><div class="headline">이 스프링은 ${fmt(r.F,1)} N 으로 밀어요</div>
375	      <div class="detail">4번에 도어 크기와 무게를 넣으면 충분한지 알려줄게요!</div>`;
376	  } else if (pass_h) {
377	    big.className = "big-result good";
378	    big.innerHTML = `<div class="emoji">🎉</div><div class="headline">어느 방향이든 도어를 잘 밀어내요!</div>
379	      <div class="detail">내 스프링 힘 <b>${fmt(r.F,1)} N</b> — 눕혀서도 세워서도 충분해요.</div>`;
380	  } else if (pass_v) {
381	    big.className = "big-result warn";
382	    big.innerHTML = `<div class="emoji">😅</div><div class="headline">세워서 쓰면 OK, 눕히면 약해요</div>
383	      <div class="detail">세워서(마찰만)는 되는데, 눕혀서 무게를 들어올리기엔 힘이 모자라요.<br>
384	      👉 철사를 굵게, 동그라미를 작게 해 보세요!</div>`;
385	  } else {
386	    big.className = "big-result bad";
387	    big.innerHTML = `<div class="emoji">😟</div><div class="headline">힘이 약해요</div>
388	      <div class="detail">눕혀서도 세워서도 도어를 밀어내기 부족해요.<br>
389	      👉 철사를 굵게, 동그라미를 작게, 바퀴를 적게 해 보세요!</div>`;
390	  }
391	
392	  // ---- 힘 막대 (스프링 / 눕혀서 / 세워서) ----
393	  const springF = r ? r.F : 0;
394	  const maxF = Math.max(springF, F_req_h || 0, F_req_v || 0) * 1.2 || 1;
395	  $("barSpring").style.width = Math.min(100, springF / maxF * 100) + "%";
396	  $("barSpringVal").textContent = r ? fmt(springF, 1) + " N" : "–";
397	  $("needHName").innerHTML = "🛏️ 눕혀서(무게 들기) 필요" + (pass_h != null ? (pass_h ? " ✅" : " ❌") : "");
398	  $("needVName").innerHTML = "🧍 세워서(마찰만) 필요" + (pass_v != null ? (pass_v ? " ✅" : " ❌") : "");
399	  if (haveDoor) {
400	    $("barNeedH").style.width = Math.min(100, F_req_h / maxF * 100) + "%";
401	    $("barNeedHVal").textContent = fmt(F_req_h, 1) + " N";
402	    $("barNeedV").style.width = Math.min(100, F_req_v / maxF * 100) + "%";
403	    $("barNeedVVal").textContent = fmt(F_req_v, 1) + " N";
404	  } else {
405	    $("barNeedH").style.width = "0%"; $("barNeedHVal").textContent = "–";
406	    $("barNeedV").style.width = "0%"; $("barNeedVVal").textContent = "–";
407	  }
408	
409	  // ---- 칩 (무게 비유 + 튼튼함) ----
410	  $("chipWeight").textContent = r ? "💪 미는 힘 = " + weightAnalogy(springF) : "무게로 치면 –";
411	  const chipSafe = $("chipSafe");
412	  if (r && r.SF != null) {
413	    if (r.SF >= 1.5)      chipSafe.textContent = "🛡️ 튼튼해요 (안 부러져요)";
414	    else if (r.SF >= 1.0) chipSafe.textContent = "🤔 조금 빠듯해요";
415	    else                  chipSafe.textContent = "⚠️ 부러질 수 있어요!";
416	  } else {
417	    chipSafe.textContent = "🛡️ 튼튼함 –";
418	  }
419	
420	  drawChart(r, thetaDeg, haveDoor ? M_grav : null);
421	  drawDiagram(d, D, thetaDeg, r ? r.C : 0);
422	}
423	
424	// ===================== 그래프 (어른용) =====================
425	function drawChart(r, thetaMax, M_req) {
426	  const svg = $("chart");
427	  const W = 520, H = 280, padL = 56, padB = 40, padT = 16, padR = 16;
428	  const x0 = padL, x1 = W - padR, y0 = H - padB, y1 = padT;
429	  if (!r || thetaMax <= 0) { svg.innerHTML = `<text x="${W/2}" y="${H/2}" fill="#6b7280" text-anchor="middle">입력값을 채우세요</text>`; return; }
430	  const Mmax = Math.max(r.M, M_req || 0) * 1.15 || 1;
431	  const sx = (t) => x0 + (t / thetaMax) * (x1 - x0);
432	  const sy = (m) => y0 - (m / Mmax) * (y0 - y1);
433	  let g = "";
434	  g += `<line x1="${x0}" y1="${y0}" x2="${x1}" y2="${y0}" stroke="#d7e2f2"/>`;
435	  g += `<line x1="${x0}" y1="${y0}" x2="${x0}" y2="${y1}" stroke="#d7e2f2"/>`;
436	  for (let i = 0; i <= 4; i++) {
437	    const t = thetaMax * i / 4, x = sx(t);
438	    g += `<text x="${x}" y="${y0+18}" fill="#6b7280" font-size="11" text-anchor="middle">${fmt(t,0)}°</text>`;
439	  }
440	  for (let i = 0; i <= 4; i++) {
441	    const m = Mmax * i / 4, y = sy(m);
442	    g += `<text x="${x0-8}" y="${y+4}" fill="#6b7280" font-size="11" text-anchor="end">${fmt(m,0)}</text>`;
443	  }
444	  g += `<text x="${(x0+x1)/2}" y="${H-4}" fill="#6b7280" font-size="11" text-anchor="middle">비틀림 각도 (도)</text>`;
445	  if (M_req != null && M_req > 0 && M_req <= Mmax) {
446	    const y = sy(M_req);
447	    g += `<line x1="${x0}" y1="${y}" x2="${x1}" y2="${y}" stroke="#f59e0b" stroke-dasharray="5 4"/>`;
448	    g += `<text x="${x1}" y="${y-5}" fill="#f59e0b" font-size="11" text-anchor="end">필요 ${fmt(M_req,0)}</text>`;
449	  }
450	  g += `<line x1="${sx(0)}" y1="${sy(0)}" x2="${sx(thetaMax)}" y2="${sy(r.M)}" stroke="#2f7df6" stroke-width="2.5"/>`;
451	  g += `<circle cx="${sx(thetaMax)}" cy="${sy(r.M)}" r="5" fill="#2f7df6"/>`;
452	  g += `<text x="${sx(thetaMax)-8}" y="${sy(r.M)-8}" fill="#1f2937" font-size="11" text-anchor="end">${fmt(r.M,1)} N·mm</text>`;
453	  svg.innerHTML = g;
454	}
455	
456	// ===================== 다이어그램 =====================
457	function drawDiagram(d, D, thetaDeg, C) {
458	  const svg = $("diagram");
459	  const W = 520, H = 260, cx = 230, cy = 135;
460	  if (!(d > 0 && D > d)) { svg.innerHTML = `<text x="${W/2}" y="${H/2}" fill="#6b7280" text-anchor="middle">입력값을 채우세요</text>`; return; }
461	  const R = 64, turns = 4;
462	  let g = "", path = "";
463	  const steps = turns * 40;
464	  for (let i = 0; i <= steps; i++) {
465	    const frac = i / steps;
466	    const ang = frac * turns * 2 * Math.PI;
467	    const rr = R * (0.45 + 0.55 * frac);
468	    const x = cx + rr * Math.cos(ang);
469	    const y = cy + rr * Math.sin(ang);
470	    path += (i === 0 ? "M" : "L") + x.toFixed(1) + " " + y.toFixed(1) + " ";
471	  }
472	  g += `<path d="${path}" fill="none" stroke="#2f7df6" stroke-width="2.5"/>`;
473	  const legLen = 120;
474	  g += `<line x1="${cx}" y1="${cy}" x2="${cx + legLen}" y2="${cy}" stroke="#9aa3b2" stroke-width="4" stroke-linecap="round"/>`;
475	  g += `<text x="${cx + legLen - 4}" y="${cy + 18}" fill="#6b7280" font-size="12">고정된 막대</text>`;
476	  const a = -thetaDeg * Math.PI / 180;
477	  const ex = cx + legLen * Math.cos(a), ey = cy + legLen * Math.sin(a);
478	  g += `<line x1="${cx}" y1="${cy}" x2="${ex.toFixed(1)}" y2="${ey.toFixed(1)}" stroke="#2f7df6" stroke-width="4" stroke-linecap="round"/>`;
479	  g += `<text x="${ex.toFixed(1)}" y="${(ey-10).toFixed(1)}" fill="#2f7df6" font-size="12" font-weight="bold">도어 미는 막대</text>`;
480	  const arcR = 42;
481	  const ax = cx + arcR, ay = cy;
482	  const bx = cx + arcR * Math.cos(a), by = cy + arcR * Math.sin(a);
483	  const large = thetaDeg > 180 ? 1 : 0;
484	  g += `<path d="M ${ax} ${ay} A ${arcR} ${arcR} 0 ${large} 0 ${bx.toFixed(1)} ${by.toFixed(1)}" fill="none" stroke="#f59e0b" stroke-width="2"/>`;
485	  g += `<text x="${cx + arcR + 6}" y="${cy - arcR/2}" fill="#f59e0b" font-size="13" font-weight="bold">${fmt(thetaDeg,0)}° 비틀림</text>`;
486	  g += `<text x="18" y="26" fill="#1f2937" font-size="13">철사 굵기 = ${fmt(d,2)} mm</text>`;
487	  g += `<text x="18" y="46" fill="#1f2937" font-size="13">동그라미 = ${fmt(D,2)} mm</text>`;
488	  svg.innerHTML = g;
489	}
490	
491	// ===================== 자가 테스트 (변경 없음) =====================
492	function runTests() {
493	  const out = $("tests");
494	  const r = computeSpring({ E: 207000, d: 1.0, D: 10, n: 5, L: 20, thetaDeg: 90, Sut: 2211, allowFrac: 0.80 });
495	  const cases = [
496	    ["k_turn (N·mm/회전)", r.kTurn, 383.33],
497	    ["k_deg (N·mm/도)",    r.kDeg, 1.0648],
498	    ["토크 M@90° (N·mm)",  r.M, 95.83],
499	    ["다리 끝 힘 F (N)",    r.F, 4.79],
500	    ["스프링지수 C",        r.C, 10],
501	    ["곡률보정 K_i",        r.Ki, 1.0806],
502	    ["굽힘응력 σ (MPa)",    r.sigma, 1054],
503	    ["안전율 SF",           r.SF, 1.678],
504	  ];
505	  let html = "", allPass = true;
506	  cases.forEach(([label, got, exp]) => {
507	    const tol = Math.abs(exp) * 0.01 + 1e-9;
508	    const pass = Math.abs(got - exp) <= tol;
509	    if (!pass) allPass = false;
510	    html += `<div class="test-row"><span>${label}</span><span class="${pass?'pass':'fail'}">${pass?'✅':'❌'} ${fmt(got,3)} (기대 ${exp})</span></div>`;
511	  });
512	  html = `<div style="margin-bottom:6px">전체: <b class="${allPass?'pass':'fail'}">${allPass?'✅ PASS':'❌ FAIL'}</b></div>` + html;
513	  out.innerHTML = html;
514	}
515	
516	// ===================== 이벤트 =====================
517	function bind() {
518	  populateMaterials();
519	  applyMaterial();
520	  $("material").addEventListener("change", () => { applyMaterial(); render(); });
521	  ["d","diaInput","n","L","theta","dw","dd","dh","dweight"].forEach(id =>
522	    $(id).addEventListener("input", () => { if (id === "d") applyMaterial(); render(); }));
523	
524	  $("dmode").querySelectorAll("button").forEach(b =>
525	    b.addEventListener("click", () => {
526	      diaMode = b.dataset.mode;
527	      $("dmode").querySelectorAll("button").forEach(x => x.classList.toggle("active", x === b));
528	      $("diaLabel").textContent = { mean: "가운데 지름", od: "바깥 지름", id: "안쪽 지름" }[diaMode];
529	      render();
530	    }));
531	
532	  runTests();
533	  render();
534	}
535	bind();
536	</script>
537	</body>
538	</html>
