input.new_string:
function tensileStrength(A, m, d) {
  if (A == null || m == null) return null;
  return A * Math.pow(d, -m);
}

// 토션스프링 피로 (Shigley): R=0 굽힘 피로강도 비율 → Goodman 선도
// 값 = 최대 굽힘응력 / Sut (A228·302SS 기준 근사). [수명버킷][쇼트피닝]
const FATIGUE_FRAC = {
  low:  { no: 0.80, yes: 0.80 }, // 가끔(~1만 회): 사실상 정적
  mid:  { no: 0.53, yes: 0.62 }, // 보통(~10만 회)
  high: { no: 0.50, yes: 0.60 }, // 자주(100만+ 회): 무한수명 근사
};

// 스프링은 θ0(닫힘)~θ(열림)을 왕복. σ는 각도에 선형 비례(Ki 일정).
function computeFatigue(spring, thetaDeg, theta0Deg, Sut, lifeFrac) {
  if (!spring || !Sut || !(thetaDeg > 0)) return null;
  const sMax = spring.sigma;                                       // θ에서 최대 굽힘응력
  const sMin = spring.sigma * (Math.min(theta0Deg, thetaDeg) / thetaDeg); // θ0에서
  const sa = Math.abs(sMax - sMin) / 2;                            // 응력진폭
  const sm = (sMax + sMin) / 2;                                    // 평균응력
  const Sr = lifeFrac * Sut;                                       // R=0 굽힘 피로강도
  const Se = (Sr / 2) / (1 - (Sr / 2) / Sut);                      // 완전반전 환산 (Goodman)
  const nf = sa <= 0 ? Infinity : 1 / (sa / Se + sm / Sut);        // 피로 안전율
  return { sMax, sMin, sa, sm, Se, Sr, nf };
}

