  // 기본: nf 정확값 (기대 ≈1.05), sa=sm≈527, se≈737
  out.default = { sigma:tc('r_sigma'), nf:tc('r_nf'), sa:tc('r_sa'), sm:tc('r_sm'), se:tc('r_se'), pre:tc('r_pre') };
  // 빈도 효과: high(기본) -> mid -> low 로 가면 nf 증가해야
  const nfHigh=tc('r_nf');
  click('#lifeMode button[data-mode="mid"]'); const nfMid=tc('r_nf');
  click('#lifeMode button[data-mode="low"]'); const nfLow=tc('r_nf');
  out.byFreq = { high:nfHigh, mid:nfMid, low:nfLow };
  // 다시 high, 피닝 on 효과 (nf 증가)
  click('#lifeMode button[data-mode="high"]'); const nfNoPeen=tc('r_nf');
  click('#peenMode button[data-mode="yes"]'); const nfPeen=tc('r_nf');
  out.byPeen = { off:nfNoPeen, on:nfPeen };
  // 프리로드 효과: θ0 올리면 sm↑ sa↓ -> nf 변화
  document.getElementById('resetBtn').click();
  const nf0=tc('r_nf'); setv('theta0','45'); const nf45=tc('r_nf');
  out.byPreload = { p0:nf0, p45:nf45, sa0:'',  pre45:tc('r_pre'), sa45:tc('r_sa'), sm45:tc('r_sm') };
  document.getElementById('resetBtn').click();
  return JSON.stringify(out,null,1);
})()

