(()=>{
  const tc=(id)=>document.getElementById(id).textContent;
  const setv=(id,v)=>{const e=document.getElementById(id);e.value=v;e.dispatchEvent(new Event('input',{bubbles:true}));};
  const click=(sel)=>document.querySelector(sel).click();
  const out={};
  // 기본(manual): 다리 응력/안전율, 끝힘
  out.manual = { legsig:tc('r_legsig'), legsf:tc('r_legsf'), F:tc('r_F'), M:tc('r_M') };
  // 자동 모드: 원하는 힘 3N -> 추천 다리 = M/3 ≈ 95.83/3 = 31.9mm
  click('#legMode button[data-mode="auto"]');
  out.auto_default = { rec:tc('legAutoOut'), F:tc('r_F'), legAutoVisible: getComputedStyle(document.getElementById('legAuto')).display, manualHidden: getComputedStyle(document.getElementById('legManual')).display };
  // 원하는 힘 5N -> 추천 = 95.83/5 = 19.2mm, 끝힘 5N
  setv('fwant','5');
  out.auto_5N = { rec:tc('legAutoOut'), F:tc('r_F') };
  // 리셋 -> manual 복귀
  document.getElementById('resetBtn').click();
  out.afterReset = { legManualShown: getComputedStyle(document.getElementById('legManual')).display, L:document.getElementById('L').value, legsf:tc('r_legsf') };
  out.tests = document.getElementById('tests').innerHTML.includes('PASS')?'PASS':'FAIL';
  return JSON.stringify(out,null,1);
})()

