// ===================== 그래프 (어른용) =====================
function drawChart(r, thetaMax, M_req) {
  const svg = $("chart");
  const W = 520, H = 280, padL = 56, padB = 40, padT = 16, padR = 16;
  const x0 = padL, x1 = W - padR, y0 = H - padB, y1 = padT;
  if (!r || thetaMax <= 0) { svg.innerHTML = `<text x="${W/2}" y="${H/2}" fill="#6b7280" text-anchor="middle">입력값을 채우세요</text>`; return; }
  const Mmax = Math.max(r.M, M_req || 0) * 1.15 || 1;
  const sx = (t) => x0 + (t / thetaMax) * (x1 - x0);
  const sy = (m) => y0 - (m / Mmax) * (y0 - y1);
  let g = "";
  g += `<line x1="${x0}" y1="${y0}" x2="${x1}" y2="${y0}" stroke="#d7e2f2"/>`;
  g += `<line x1="${x0}" y1="${y0}" x2="${x0}" y2="${y1}" stroke="#d7e2f2"/>`;
  for (let i = 0; i <= 4; i++) {
    const t = thetaMax * i / 4, x = sx(t);
    g += `<text x="${x}" y="${y0+18}" fill="#6b7280" font-size="11" text-anchor="middle">${fmt(t,0)}°</text>`;
  }
  for (let i = 0; i <= 4; i++) {
    const m = Mmax * i / 4, y = sy(m);
    g += `<text x="${x0-8}" y="${y+4}" fill="#6b7280" font-size="11" text-anchor="end">${fmt(m,0)}</text>`;
  }
  g += `<text x="${(x0+x1)/2}" y="${H-4}" fill="#6b7280" font-size="11" text-anchor="middle">비틀림 각도 (도)</text>`;
  if (M_req != null && M_req > 0 && M_req <= Mmax) {
    const y = sy(M_req);
    g += `<line x1="${x0}" y1="${y}" x2="${x1}" y2="${y}" stroke="#f59e0b" stroke-dasharray="5 4"/>`;
    g += `<text x="${x1}" y="${y-5}" fill="#f59e0b" font-size="11" text-anchor="end">필요 ${fmt(M_req,0)}</text>`;
  }
  g += `<line x1="${sx(0)}" y1="${sy(0)}" x2="${sx(thetaMax)}" y2="${sy(r.M)}" stroke="#2f7df6" stroke-width="2.5"/>`;
  g += `<circle cx="${sx(thetaMax)}" cy="${sy(r.M)}" r="5" fill="#2f7df6"/>`;
  g += `<text x="${sx(thetaMax)-8}" y="${sy(r.M)-8}" fill="#1f2937" font-size="11" text-anchor="end">${fmt(r.M,1)} N·mm</text>`;
  svg.innerHTML = g;
}

input.new_string:
// ===================== 전 구간 토크 마진 그래프 (어른용) =====================
// 도어 열림각 0(닫힘)~stroke(열림) 동안 스프링 토크 vs 저항 토크
function drawMarginChart(p) {
  const svg = $("chart");
  const W = 520, H = 280, padL = 58, padB = 42, padT = 18, padR = 18;
  const x0 = padL, x1 = W - padR, y0 = H - padB, y1 = padT;
  if (!p.haveDoor || p.stroke <= 0) {
    svg.innerHTML = `<text x="${W/2}" y="${H/2}" fill="#6b7280" text-anchor="middle">도어 값을 넣으면 전 구간 마진이 보여요</text>`;
    return;
  }
  const ymax = Math.max(p.peakM, p.M_grav, p.preM) * 1.15 || 1;
  const sx = (a) => x0 + (a / p.stroke) * (x1 - x0);
  const sy = (m) => y0 - (m / ymax) * (y0 - y1);
  let g = "";
  g += `<line x1="${x0}" y1="${y0}" x2="${x1}" y2="${y0}" stroke="#d7e2f2"/>`;
  g += `<line x1="${x0}" y1="${y0}" x2="${x0}" y2="${y1}" stroke="#d7e2f2"/>`;
  // x 라벨 (닫힘 ~ 열림)
  g += `<text x="${x0}" y="${y0+18}" fill="#6b7280" font-size="11" text-anchor="middle">닫힘</text>`;
  g += `<text x="${x1}" y="${y0+18}" fill="#6b7280" font-size="11" text-anchor="end">열림 ${fmt(p.stroke,0)}°</text>`;
  g += `<text x="${(x0+x1)/2}" y="${H-4}" fill="#6b7280" font-size="11" text-anchor="middle">도어 열림각</text>`;
  // y 눈금
  for (let i = 0; i <= 4; i++) {
    const m = ymax * i / 4, y = sy(m);
    g += `<text x="${x0-8}" y="${y+4}" fill="#6b7280" font-size="11" text-anchor="end">${fmt(m,0)}</text>`;
  }
  // 저항선 (눕혀서=실선, 세워서=점선)
  const yg = sy(p.M_grav);
  g += `<line x1="${x0}" y1="${yg}" x2="${x1}" y2="${yg}" stroke="#f59e0b" stroke-width="2"/>`;
  g += `<text x="${x1}" y="${yg-5}" fill="#f59e0b" font-size="11" text-anchor="end">🛏️ 눕혀서 저항 ${fmt(p.M_grav,0)}</text>`;
  if (p.M_fric != null && p.M_fric > 0) {
    const yf = sy(p.M_fric);
    g += `<line x1="${x0}" y1="${yf}" x2="${x1}" y2="${yf}" stroke="#f59e0b" stroke-dasharray="4 4" opacity="0.6"/>`;
    g += `<text x="${x1}" y="${yf+13}" fill="#f59e0b" font-size="10" text-anchor="end" opacity="0.85">🧍 세워서 ${fmt(p.M_fric,0)}</text>`;
  }
  // 스프링 토크선: 닫힘(preM) → 열림(peakM)
  const xa = sx(0), ya = sy(p.preM), xb = sx(p.stroke), yb = sy(p.peakM);
  g += `<line x1="${xa}" y1="${ya}" x2="${xb}" y2="${yb}" stroke="#2f7df6" stroke-width="2.5"/>`;
  g += `<circle cx="${xa}" cy="${ya}" r="4" fill="#2f7df6"/><circle cx="${xb}" cy="${yb}" r="4" fill="#2f7df6"/>`;
  g += `<text x="${xa+6}" y="${ya-7}" fill="#2f7df6" font-size="10">닫힘 ${fmt(p.preM,0)}</text>`;
  g += `<text x="${xb-6}" y="${yb-7}" fill="#2f7df6" font-size="10" text-anchor="end">열림 ${fmt(p.peakM,0)}</text>`;
  // 부족 구간이 있으면(닫힘에서 저항 위) 빨간 경고 음영
  if (p.preM < p.M_grav) {
    g += `<rect x="${x0}" y="${y1}" width="${(x1-x0)*0.5}" height="${y0-y1}" fill="#ef4444" opacity="0.06"/>`;
  }
  svg.innerHTML = g;
}

