(()=>{
  const tc=(id)=>document.getElementById(id).textContent;
  const setv=(id,v)=>{const e=document.getElementById(id);e.value=v;e.dispatchEvent(new Event('input',{bubbles:true}));};
  const chartInfo=()=>{const h=document.getElementById('chart').innerHTML;return {len:h.length, hasSpringLine:h.includes('#2f7df6'), hasResist:h.includes('눕혀서 저항'), prompt:h.includes('도어 값을 넣으면')};};
  const out={};
  // 기본 θ0=0 -> 전 구간 부족(프리로드 0)
  out.default = { chipFull:tc('chipFull'), chart:chartInfo() };
  // 프리로드 45 -> 전 구간 충분
  setv('theta0','45');
  out.preload45 = { chipFull:tc('chipFull') };
  // 마찰 비율 변경 확인: 60%로
  setv('theta0','0'); setv('fricPct','60');
  out.fric60 = { chartHasFric: document.getElementById('chart').innerHTML.includes('세워서') };
  // 도어 비우면 안내 문구
  setv('dweight','0');
  out.noDoor = { chipFull:tc('chipFull'), chartPrompt: document.getElementById('chart').innerHTML.includes('도어 값을 넣으면') };
  document.getElementById('resetBtn').click();
  out.afterReset = { chipFull:tc('chipFull'), fricPct:document.getElementById('fricPct').value, theta0:document.getElementById('theta0').value };
  out.tests = document.getElementById('tests').innerHTML.includes('PASS')?'PASS':'FAIL';
  return JSON.stringify(out,null,1);
})()

