400	function computeSpring(p) {
401	  const { E, d, D, n, L, thetaDeg } = p;
402	  const C = D / d;
403	  const kTurn = (E * Math.pow(d, 4)) / (10.8 * D * n);
404	  const kDeg = kTurn / 360;
405	  const M = kDeg * thetaDeg;
406	  const F = L > 0 ? M / L : 0;
407	  const Ki = (4 * C * C - C - 1) / (4 * C * (C - 1));
408	  const sigma = Ki * 32 * M / (Math.PI * Math.pow(d, 3));
409	  let Sut = p.Sut, sigmaAllow = null, SF = null;
410	  if (Sut && Sut > 0) {
411	    sigmaAllow = p.allowFrac * Sut;
412	    SF = sigma > 0 ? sigmaAllow / sigma : Infinity;
413	  }
414	  return { C, kTurn, kDeg, M, F, Ki, sigma, Sut, sigmaAllow, SF };
415	}
416	function tensileStrength(A, m, d) {
417	  if (A == null || m == null) return null;
418	  return A * Math.pow(d, -m);
419	}
