421	// 토션스프링 피로 (Shigley): R=0 굽힘 피로강도 비율 → Goodman 선도
422	// 값 = 최대 굽힘응력 / Sut (A228·302SS 기준 근사). [수명버킷][쇼트피닝]
423	const FATIGUE_FRAC = {
424	  low:  { no: 0.80, yes: 0.80 }, // 가끔(~1만 회): 사실상 정적
425	  mid:  { no: 0.53, yes: 0.62 }, // 보통(~10만 회)
426	  high: { no: 0.50, yes: 0.60 }, // 자주(100만+ 회): 무한수명 근사
