429	// 스프링은 θ0(닫힘)~θ(열림)을 왕복. σ는 각도에 선형 비례(Ki 일정).
430	function computeFatigue(spring, thetaDeg, theta0Deg, Sut, lifeFrac) {
431	  if (!spring || !Sut || !(thetaDeg > 0)) return null;
432	  const sMax = spring.sigma;                                       // θ에서 최대 굽힘응력
433	  const sMin = spring.sigma * (Math.min(theta0Deg, thetaDeg) / thetaDeg); // θ0에서
434	  const sa = Math.abs(sMax - sMin) / 2;                            // 응력진폭
435	  const sm = (sMax + sMin) / 2;                                    // 평균응력
436	  const Sr = lifeFrac * Sut;                                       // R=0 굽힘 피로강도
437	  const Se = (Sr / 2) / (1 - (Sr / 2) / Sut);                      // 완전반전 환산 (Goodman)
438	  const nf = sa <= 0 ? Infinity : 1 / (sa / Se + sm / Sut);        // 피로 안전율
439	  return { sMax, sMin, sa, sm, Se, Sr, nf };
440	}
