682	// ===================== 도어 애니메이션 =====================
683	const easeOut = (p) => 1 - Math.pow(1 - p, 3);
684	const easeInOut = (p) => (p < 0.5 ? 4*p*p*p : 1 - Math.pow(-2*p + 2, 3) / 2);
685	function easeOutBack(p) { const c1 = 1.70158, c3 = c1 + 1; return 1 + c3*Math.pow(p-1,3) + c1*Math.pow(p-1,2); }
686	
687	// 시간 t(0~1)에서의 도어 열림각(도, 0=닫힘) — tier별 거동
688	function doorAngleAt(t, openAngle, tier) {
689	  const openEnd = 0.30, holdEnd = 0.44;
690	  if (t < openEnd) return openAngle * easeInOut(t / openEnd);   // 손으로 연다
691	  if (t < holdEnd) return openAngle;                            // 잠깐 멈춤
692	  const p = (t - holdEnd) / (1 - holdEnd);                      // 놓은 뒤 닫힘 단계
693	  if (tier === "good") {                                        // 빠르게 탁! (살짝 바운스)
694	    return Math.max(0, openAngle * (1 - easeOutBack(p)));
695	  } else if (tier === "warn") {                                 // 천천히 닫힘
696	    return openAngle * (1 - easeOut(p));
697	  } else if (tier === "bad") {                                  // 반쯤 닫히다 도로 열림
698	    if (p < 0.5) return openAngle * (1 - 0.45 * easeOut(p / 0.5));
699	    return openAngle * (0.55 + 0.45 * easeInOut((p - 0.5) / 0.5));
700	  }
701	  return 0; // idle
702	}
