function drawLegAnim(animL, fullL, fullM) {
  const svg = $("legAnim");
  if (!svg) return;
  const W = 520, H = 185, cx = 78, cy = 80, coilR = 28, maxLegPx = 310;
  const legPx = fullL > 0 ? Math.max(0, (animL / fullL) * maxLegPx) : 0;
  const legEndX = cx + legPx;
  const F = (fullM > 0 && animL > 0) ? fullM / animL : 0;
  const arrowLen = (fullM > 0 && fullL > 0 && animL > 0)
    ? Math.min(82, 38 * (fullL / animL)) : 0;
  let g = "";
  // 가이드라인 (최대 다리 위치)
  g += `<line x1="${cx}" y1="${cy}" x2="${cx + maxLegPx}" y2="${cy}" stroke="#dce6f5" stroke-dasharray="6 5"/>`;
  // 스프링 코일
  let sp = ""; const R0 = 4, R1 = coilR, turns = 3.5, steps = 70;
  for (let i = 0; i <= steps; i++) {
    const frac = i / steps, ang = frac * turns * 2 * Math.PI, rr = R0 + (R1 - R0) * frac;
    sp += (i === 0 ? "M" : "L") + (cx + rr * Math.cos(ang)).toFixed(1) + " " + (cy + rr * Math.sin(ang)).toFixed(1) + " ";
  }
  g += `<path d="${sp}" fill="none" stroke="#2f7df6" stroke-width="2"/>`;
  // 다리(레그)
  if (legPx > 4 && animL > 0.5) {
    g += `<line x1="${cx}" y1="${cy}" x2="${legEndX.toFixed(1)}" y2="${cy}" stroke="#2563eb" stroke-width="5" stroke-linecap="round"/>`;
    g += `<circle cx="${legEndX.toFixed(1)}" cy="${cy}" r="5" fill="#2563eb"/>`;
  }
  // 힘 화살표 (다리 끝에서 아래로)
  if (arrowLen > 3 && legPx > 18) {
    const ax = legEndX, ay = cy + 6, tipY = ay + arrowLen;
    g += `<line x1="${ax.toFixed(1)}" y1="${ay}" x2="${ax.toFixed(1)}" y2="${tipY.toFixed(1)}" stroke="#ef4444" stroke-width="3" stroke-linecap="round"/>`;
    g += `<polygon points="${ax.toFixed(1)},${(tipY+7).toFixed(1)} ${(ax-5).toFixed(1)},${tipY.toFixed(1)} ${(ax+5).toFixed(1)},${tipY.toFixed(1)}" fill="#ef4444"/>`;
    if (F > 0 && animL > 1) {
      const lx = ax > 400 ? ax - 8 : ax + 9, anc = ax > 400 ? "end" : "start";
      g += `<text x="${lx.toFixed(1)}" y="${((ay + tipY) / 2 + 4).toFixed(1)}" fill="#ef4444" font-size="12" font-weight="bold" text-anchor="${anc}">F = ${fmt(F,1)} N</text>`;
    }
  }
  // L 치수선 (다리 위쪽)
  if (legPx > 18 && animL > 0.5) {
    const dimY = cy - 24, lbX = (cx + legEndX) / 2;
    g += `<line x1="${cx}" y1="${dimY}" x2="${legEndX.toFixed(1)}" y2="${dimY}" stroke="#f59e0b" stroke-width="1.5"/>`;
    g += `<line x1="${cx}" y1="${dimY-5}" x2="${cx}" y2="${dimY+5}" stroke="#f59e0b" stroke-width="1.5"/>`;
    g += `<line x1="${legEndX.toFixed(1)}" y1="${dimY-5}" x2="${legEndX.toFixed(1)}" y2="${dimY+5}" stroke="#f59e0b" stroke-width="1.5"/>`;
    g += `<text x="${lbX.toFixed(1)}" y="${(dimY-6).toFixed(1)}" fill="#f59e0b" font-size="13" text-anchor="middle" font-weight="bold">L = ${animL.toFixed(0)} mm</text>`;
  }
  // 힌지 중심
  g += `<circle cx="${cx}" cy="${cy}" r="6" fill="#1f2937"/>`;
  g += `<text x="${cx}" y="${cy+24}" fill="#6b7280" font-size="11" text-anchor="middle">힌지</text>`;
  // 토크 고정 안내
  if (fullM > 0) {
    g += `<text x="${W-8}" y="18" fill="#6b7280" font-size="12" text-anchor="end">M = ${fmt(fullM,1)} N·mm (일정)</text>`;
    g += `<text x="${W-8}" y="35" fill="#9aa3b2" font-size="11" text-anchor="end">F = M ÷ L</text>`;
  } else {
    g += `<text x="${W/2}" y="${H/2+8}" fill="#b0b8cc" font-size="14" text-anchor="middle">스프링 값을 넣으면 시작돼요</text>`;
  }
  svg.innerHTML = g;
}

// ===================== 전 구간 토크 마진 그래프 (어른용) =====================
// 도어 열림각 0(닫힘)~stroke(열림) 동안 스프링 토크 vs 저항 토크
function drawMarginChart(p) {
  const svg = $("chart");
  const W = 520, H = 280, padL = 58, padB = 42, padT = 18, padR = 18;
  const x0 = padL, x1 = W - padR, y0 = H - padB, y1 = padT;
  if (!p.haveDoor || p.stroke <= 0) {
    svg.innerHTML = `<text x="${W/2}" y="${H/2}" fill="#6b7280" text-anchor="middle">도어 값을 넣으면 전 구간 마진이 보여요</text>`;
    return;
  }

