  // 토션스프링 구조: 코일 몸체 + 고정 다리(왼쪽) + 자유 다리(오른쪽, 애니메이션)
  const W = 520, H = 185, cx = 130, cy = 90, coilR = 36;
  const legStartX = cx + coilR;   // 자유 다리 시작 = 코일 오른쪽 끝
  const maxLegPx = 250;
  const legPx = fullL > 0 ? Math.max(0, (animL / fullL) * maxLegPx) : 0;
  const legEndX = legStartX + legPx;
  const F = (fullM > 0 && animL > 0) ? fullM / animL : 0;
  const arrowLen = (fullM > 0 && fullL > 0 && animL > 0)
    ? Math.min(72, 38 * (fullL / animL)) : 0;
  let g = "";

  // ---- 코일 몸체 (토션스프링 감김 부분) ----
  g += `<circle cx="${cx}" cy="${cy}" r="${coilR}" fill="#eef3fb" stroke="#2f7df6" stroke-width="2.5"/>`;
  for (let i = -2; i <= 2; i++) {
    const yy = cy + i * (coilR / 3);
    g += `<line x1="${(cx - coilR * 0.78).toFixed(1)}" y1="${yy.toFixed(1)}" x2="${(cx + coilR * 0.78).toFixed(1)}" y2="${yy.toFixed(1)}" stroke="#2f7df6" stroke-width="1.5" opacity="0.35"/>`;
  }
  g += `<text x="${cx}" y="${cy + 5}" fill="#2f7df6" font-size="10" text-anchor="middle" font-weight="bold">코일</text>`;

  // ---- 고정 다리 (왼쪽으로 뻗음, 벽에 고정됨) ----
  const fixedStartX = cx - coilR;    // 94
  const fixedEndX   = fixedStartX - 46; // 48
  g += `<line x1="${fixedStartX}" y1="${cy}" x2="${fixedEndX}" y2="${cy}" stroke="#9aa3b2" stroke-width="5" stroke-linecap="round"/>`;
  // 고정단 벽
  g += `<rect x="${fixedEndX - 8}" y="${cy - 15}" width="9" height="30" fill="#c5cdd8" rx="2"/>`;
  for (let yy = cy - 13; yy <= cy + 9; yy += 7) {
    g += `<line x1="${fixedEndX - 8}" y1="${yy}" x2="${fixedEndX - 15}" y2="${yy + 7}" stroke="#9aa3b2" stroke-width="1.5"/>`;
  }
  g += `<text x="${(fixedStartX - 23)}" y="${cy + 22}" fill="#9aa3b2" font-size="10" text-anchor="middle">고정 다리</text>`;

  // ---- 자유 다리 가이드라인 ----
  g += `<line x1="${legStartX}" y1="${cy}" x2="${legStartX + maxLegPx}" y2="${cy}" stroke="#dce6f5" stroke-dasharray="6 5"/>`;

  // ---- 자유 다리 (토션스프링 다리 — 도어를 밀어냄, 애니메이션) ----
  if (legPx > 4 && animL > 0.5) {
    g += `<line x1="${legStartX}" y1="${cy}" x2="${legEndX.toFixed(1)}" y2="${cy}" stroke="#2563eb" stroke-width="5" stroke-linecap="round"/>`;
    g += `<circle cx="${legEndX.toFixed(1)}" cy="${cy}" r="5" fill="#2563eb"/>`;
  }
  if (legPx > 55) {
    const lblX = legStartX + legPx * 0.5;
    g += `<text x="${lblX.toFixed(1)}" y="${cy + 22}" fill="#2563eb" font-size="10" text-anchor="middle">자유 다리 (힘 전달)</text>`;
  }

  // ---- 힘 화살표 (자유 다리 끝 → 아래, 도어를 미는 방향) ----
  if (arrowLen > 3 && legPx > 18) {
    const ax = legEndX, ay = cy + 6, tipY = ay + arrowLen;
    g += `<line x1="${ax.toFixed(1)}" y1="${ay}" x2="${ax.toFixed(1)}" y2="${tipY.toFixed(1)}" stroke="#ef4444" stroke-width="3" stroke-linecap="round"/>`;
    g += `<polygon points="${ax.toFixed(1)},${(tipY+7).toFixed(1)} ${(ax-5).toFixed(1)},${tipY.toFixed(1)} ${(ax+5).toFixed(1)},${tipY.toFixed(1)}" fill="#ef4444"/>`;
