    }
  }

  // ---- 다리 길이 치수선 ----
  if (legPx > 18 && animL > 0.5) {
    const dimY = cy - 30, lbX = legStartX + legPx / 2;
    g += `<line x1="${legStartX}" y1="${dimY}" x2="${legEndX.toFixed(1)}" y2="${dimY}" stroke="#f59e0b" stroke-width="1.5"/>`;
    g += `<line x1="${legStartX}" y1="${dimY-5}" x2="${legStartX}" y2="${dimY+5}" stroke="#f59e0b" stroke-width="1.5"/>`;
    g += `<line x1="${legEndX.toFixed(1)}" y1="${dimY-5}" x2="${legEndX.toFixed(1)}" y2="${dimY+5}" stroke="#f59e0b" stroke-width="1.5"/>`;
