       const TL = 2600, tL = ((now - _animStart) % TL) / TL;
       const fL = legAnimState.L, fM = legAnimState.M;
       if (fL > 0) {
         let af;
         if (tL < 0.62)      af = 0.15 + 0.85 * easeOut(tL / 0.62);
         else if (tL < 0.82) af = 1.0;
         else                af = 1.0 - 0.85 * easeInOut((tL - 0.82) / 0.18);
         drawLegAnim(fL * af, fL, fM);
       } else { drawLegAnim(0, 1, 0); }
       ```
