// ===================== 렌더 =====================
function render() {
  const mat = MATERIALS[$("material").value];
  const d = parseFloat($("d").value) || 0;
  const D = currentMeanD(d);
  const n = parseFloat($("n").value) || 0;
  const thetaDeg = parseFloat($("theta").value) || 0;
  const E = parseFloat($("E").value) || 0;
  const Sut = parseFloat($("Sut").value) || null;

  const valid = d > 0 && D > d && n > 0 && E > 0;
  // 토크 M은 다리 길이와 무관 → 먼저 산출 (L=1 기준)
  const base = valid ? computeSpring({ E, d, D, n, L: 1, thetaDeg, Sut, allowFrac: mat.allowFrac }) : null;

  // 다리 길이 결정: 직접 입력 vs 원하는 힘으로 자동 계산 (L = M / F)
  let L;
  if (legMode === "auto") {
    const Fwant = parseFloat($("fwant").value) || 0;
    L = (base && Fwant > 0) ? base.M / Fwant : 0;
    $("legAutoOut").textContent = (L > 0) ? fmt(L, 1) + " mm" : "–";
  } else {
    L = parseFloat($("L").value) || 0;
  }

  const r = valid ? computeSpring({ E, d, D, n, L, thetaDeg, Sut, allowFrac: mat.allowFrac }) : null;
  legAnimState.L = L > 0 ? L : 0;
  legAnimState.M = r ? r.M : 0;

  // 어른용 숫자
  $("r_kdeg").textContent  = r ? fmt(r.kDeg, 3) : "–";
  $("r_C").textContent     = r ? fmt(r.C, 2) : "–";
  $("r_M").textContent     = r ? fmt(r.M, 1) : "–";
  $("r_F").textContent     = r ? fmt(r.F, 2) : "–";
  $("r_sigma").textContent = r ? fmt(r.sigma, 0) : "–";
  $("r_sf").textContent    = r && r.SF != null ? fmt(r.SF, 2) : "–";

  // ---- 도어 크기·무게로 필요한 힘 계산 ----
  const dwid = parseFloat($("dw").value) || 0;
  const ddep = parseFloat($("dd").value) || 0;
  const dhei = parseFloat($("dh").value) || 0;
  const weightG = parseFloat($("dweight").value) || 0;
  const armDoor = Math.max(dwid, ddep, dhei) / 2;        // 무게중심까지 거리 (mm)
  const Wforce  = weightG / 1000 * G;                    // 도어 무게 힘 (N)
  const M_grav  = Wforce * armDoor;                      // 🛏️ 눕혀서: 무게 들기 토크 (N·mm)
  const fricFrac = Math.max(0, (parseFloat($("fricPct").value) || 0) / 100);
  const M_fric  = fricFrac * M_grav;                     // 🧍 세워서: 마찰만 (사용자 입력 비율)
  const haveDoor = weightG > 0 && armDoor > 0 && L > 0;
  const F_req_h = haveDoor ? M_grav / L : null;          // 비교용 힘 (N, 스프링 팔 기준)
  const F_req_v = haveDoor ? M_fric / L : null;
  const pass_h = (r && haveDoor) ? r.M >= M_grav : null;
  const pass_v = (r && haveDoor) ? r.M >= M_fric : null;

  // ---- 결과 상태 결정 (큰 결과 + 모바일 요약 공용) ----
  let st;
  if (!r) {
    st = { cls: "warn", emoji: "🤔", headline: "값을 채워 주세요",
           detail: "철사 굵기·동그라미 크기·바퀴 수를 넣으면 실험이 시작돼요!" };
  } else if (!haveDoor) {
    st = { cls: "good", emoji: "💙", headline: `이 스프링은 ${fmt(r.F,1)} N 으로 밀어요`,
           detail: "4번에 도어 크기와 무게를 넣으면 충분한지 알려줄게요!" };
  } else if (pass_h) {
    st = { cls: "good", emoji: "🎉", headline: "어느 방향이든 도어를 잘 밀어내요!",
           detail: `내 스프링 힘 <b>${fmt(r.F,1)} N</b> — 눕혀서도 세워서도 충분해요.` };
  } else if (pass_v) {
    st = { cls: "warn", emoji: "😅", headline: "세워서 쓰면 OK, 눕히면 약해요",
           detail: "세워서(마찰만)는 되는데, 눕혀서 무게를 들어올리기엔 힘이 모자라요.<br>👉 철사를 굵게, 동그라미를 작게 해 보세요!" };
  } else {
    st = { cls: "bad", emoji: "😟", headline: "힘이 약해요",
           detail: "눕혀서도 세워서도 도어를 밀어내기 부족해요.<br>👉 철사를 굵게, 동그라미를 작게, 바퀴를 적게 해 보세요!" };
  }
  const big = $("bigForce");

