mini.innerHTML = `<span class="e">${st.emoji}</span><span>${st.headline}</span>`;

// ---- 힘 막대 (스프링 / 눕혀서 / 세워서) ----
const springF = r ? r.F : 0;
const maxF = Math.max(springF, F_req_h || 0, F_req_v || 0) * 1.2 || 1;
let springTone = "spring";
if (r && haveDoor) springTone = pass_h ? "good" : (pass_v ? "warn" : "bad");
$("barSpring").className = "bar-fill " + springTone;
$("barSpring").style.width = Math.min(100, springF / maxF * 100) + "%";
$("barSpringVal").textContent = r ? fmt(springF, 1) + " N" : "–";
$("needHName").innerHTML = "🛏️ 눕혀서(무게 들기) 필요" + badge(pass_h);
$("needVName").innerHTML = "🧍 세워서(마찰만) 필요" + badge(pass_v);
if (haveDoor) {
  $("barNeedH").style.width = Math.min(100, F_req_h / maxF * 100) + "%";
  $("barNeedHVal").textContent = fmt(F_req_h, 1) + " N";
  $("barNeedV").style.width = Math.min(100, F_req_v / maxF * 100) + "%";
  $("barNeedVVal").textContent = fmt(F_req_v, 1) + " N";
} else {
  $("barNeedH").style.width = "0%"; $("barNeedHVal").textContent = "–";
  $("barNeedV").style.width = "0%"; $("barNeedVVal").textContent = "–";
}

// ---- 칩 (무게 비유 + 튼튼함) ----
$("chipWeight").textContent = r ? "💪 미는 힘 = " + weightAnalogy(springF) : "무게로 치면 –";
const chipSafe = $("chipSafe");
if (r && r.SF != null) {
  if (r.SF >= 1.5)      chipSafe.textContent = "🛡️ 한 번 쓸 땐 튼튼";
  else if (r.SF >= 1.0) chipSafe.textContent = "🛡️ 한 번 쓸 땐 빠듯";
  else                  chipSafe.textContent = "⚠️ 한 번에도 부러질 수 있어요!";
} else {
  chipSafe.textContent = "🛡️ 한 번 쓸 때 –";
}

// ---- 프리로드(닫힘 유지력) + 피로(반복 내구) ----
const theta0 = Math.max(0, Math.min(thetaDeg || 0, parseFloat($("theta0").value) || 0));
const lifeFrac = FATIGUE_FRAC[lifeMode][peenMode];
const preM = r ? r.kDeg * theta0 : 0;
const preF = (r && L > 0) ? preM / L : 0;
const fat = (r && Sut) ? computeFatigue(r, thetaDeg, theta0, Sut, lifeFrac) : null;

$("r_pre").textContent = r ? fmt(preM, 1) : "–";
$("r_sa").textContent  = fat ? fmt(fat.sa, 0) : "–";
$("r_sm").textContent  = fat ? fmt(fat.sm, 0) : "–";
$("r_se").textContent  = fat ? fmt(fat.Se, 0) : "–";
$("r_nf").textContent  = fat ? (fat.nf === Infinity ? "∞" : fmt(fat.nf, 2)) : "–";

const lifeLabel = { low: "1만", mid: "10만", high: "100만" }[lifeMode];
const chipFat = $("chipFatigue");
if (fat) {
  const nfStr = fat.nf === Infinity ? "∞" : fmt(fat.nf, 1);
  if (fat.nf >= 1.5)      chipFat.textContent = `🔁 ${lifeLabel}회도 튼튼 (피로 ${nfStr})`;
  else if (fat.nf >= 1.0) chipFat.textContent = `🔁 ${lifeLabel}회는 빠듯 (피로 ${nfStr})`;
  else                    chipFat.textContent = `⚠️ ${lifeLabel}회 반복하면 부러져요! (피로 ${nfStr})`;
} else {
  chipFat.textContent = "🔁 반복 –";
}

const chipHold = $("chipHold");
chipHold.textContent = (theta0 > 0 && r) ? `🔒 닫힘 유지력 ${fmt(preF, 1)} N` : "🔒 프리로드 없음";

// ---- 다리(곧은 부분) 굽힘응력: 뿌리 모멘트 = 스프링 토크 M, 곡률보정 없음 ----
const legSig = r ? 32 * r.M / (Math.PI * Math.pow(d, 3)) : null;
const legSF  = (legSig && Sut) ? (mat.allowFrac * Sut) / legSig : null;
$("r_legsig").textContent = legSig ? fmt(legSig, 0) : "–";
$("r_legsf").textContent  = legSF ? fmt(legSF, 2) : "–";

// ---- 전 구간(닫힘→열림) 토크 마진 ----
// 스프링 토크 최소 = 닫힘 위치(프리로드) preM, 최대 = 열림 peakM.
// 저항(눕혀서)은 보수적으로 전 구간 일정(M_grav)으로 본다 → 최약점은 닫힘.
const stroke = Math.max(0, thetaDeg - theta0);
const peakM = r ? r.M : 0;
let fullPass = null, minMargin = null;
if (r && haveDoor) { minMargin = preM - M_grav; fullPass = minMargin >= 0; }

const chipFull = $("chipFull");
if (r && haveDoor) {
  chipFull.textContent = fullPass
    ? "🔄 전 구간(닫힘~열림) 충분"
    : `⚠️ 닫힘 근처 부족 (여유 ${fmt(minMargin, 0)} N·mm) — 프리로드를 주세요`;
} else {
  chipFull.textContent = "🔄 전 구간 –";
}

drawMarginChart({
  haveDoor: !!(r && haveDoor),
  stroke, preM, peakM,
  M_grav: haveDoor ? M_grav : 0,
  M_fric: haveDoor ? M_fric : 0,
});
drawDiagram(d, D, thetaDeg, r ? r.C : 0);

// ---- 도어 애니메이션 상태 + 설명 ----
animState.tier = r ? st.cls : "idle";
animState.openAngle = Math.max(0, Math.min(160, thetaDeg));
const caps = {
