// ===================== 도어 애니메이션 =====================
const easeOut = (p) => 1 - Math.pow(1 - p, 3);
const easeInOut = (p) => (p < 0.5 ? 4*p*p*p : 1 - Math.pow(-2*p + 2, 3) / 2);
function easeOutBack(p) { const c1 = 1.70158, c3 = c1 + 1; return 1 + c3*Math.pow(p-1,3) + c1*Math.pow(p-1,2); }

// 시간 t(0~1)에서의 도어 열림각(도, 0=닫힘) — tier별 거동
function doorAngleAt(t, openAngle, tier) {
  const openEnd = 0.30, holdEnd = 0.44;
  if (t < openEnd) return openAngle * easeInOut(t / openEnd);   // 손으로 연다
  if (t < holdEnd) return openAngle;                            // 잠깐 멈춤
  const p = (t - holdEnd) / (1 - holdEnd);                      // 놓은 뒤 닫힘 단계
  if (tier === "good") {                                        // 빠르게 탁! (살짝 바운스)
    return Math.max(0, openAngle * (1 - easeOutBack(p)));
  } else if (tier === "warn") {                                 // 천천히 닫힘
    return openAngle * (1 - easeOut(p));
  } else if (tier === "bad") {                                  // 반쯤 닫히다 도로 열림
    if (p < 0.5) return openAngle * (1 - 0.45 * easeOut(p / 0.5));
    return openAngle * (0.55 + 0.45 * easeInOut((p - 0.5) / 0.5));
  }
  return 0; // idle
}

function drawDoorScene(openDeg, tier) {
  const svg = $("doorAnim");
  if (!svg) return;
  const hx = 140, hy = 172, doorLen = 215, th = 20;
  const col = tier === "good" ? "#16a34a" : tier === "warn" ? "#f59e0b" : tier === "bad" ? "#ef4444" : "#2f7df6";
  let g = "";
  // 카트리지 본체
  g += `<rect x="118" y="180" width="310" height="48" rx="10" fill="#dbe6f7" stroke="#c2d3ee"/>`;
  g += `<text x="273" y="210" fill="#6b7280" font-size="12" text-anchor="middle">카트리지 본체</text>`;
  // 닫힘 위치 가이드
  g += `<line x1="${hx}" y1="${hy}" x2="${hx + doorLen}" y2="${hy}" stroke="#c2d3ee" stroke-dasharray="5 5"/>`;
  g += `<text x="${hx + doorLen}" y="${hy - 8}" fill="#9aa3b2" font-size="11" text-anchor="end">닫힘 위치</text>`;
  // 힌지의 스프링 코일
  let sp = ""; const R0 = 4, R1 = 17, turns = 3, steps = 80;
  for (let i = 0; i <= steps; i++) {
    const frac = i / steps, ang = frac * turns * 2 * Math.PI, rr = R0 + (R1 - R0) * frac;
    sp += (i === 0 ? "M" : "L") + (hx + rr*Math.cos(ang)).toFixed(1) + " " + (hy + rr*Math.sin(ang)).toFixed(1) + " ";
  }
  g += `<path d="${sp}" fill="none" stroke="${col}" stroke-width="2"/>`;
  // 도어 패널 (힌지 기준 회전)
  g += `<g transform="rotate(${(-openDeg).toFixed(2)} ${hx} ${hy})">
          <rect x="${hx}" y="${hy - th/2}" width="${doorLen}" height="${th}" rx="${th/2}" fill="${col}" opacity="0.92"/>
          <circle cx="${hx + doorLen - 14}" cy="${hy}" r="4" fill="#fff" opacity="0.85"/>
        </g>`;

