function drawDiagram(d, D, thetaDeg, C) {
  const svg = $("diagram");
  const W = 520, H = 260, cx = 230, cy = 135;
  if (!(d > 0 && D > d)) { svg.innerHTML = `<text x="${W/2}" y="${H/2}" fill="#6b7280" text-anchor="middle">입력값을 채우세요</text>`; return; }
  const R = 64, turns = 4;
  let g = "", path = "";
  const steps = turns * 40;
  for (let i = 0; i <= steps; i++) {
    const frac = i / steps;
    const ang = frac * turns * 2 * Math.PI;
    const rr = R * (0.45 + 0.55 * frac);
    const x = cx + rr * Math.cos(ang);
    const y = cy + rr * Math.sin(ang);
    path += (i === 0 ? "M" : "L") + x.toFixed(1) + " " + y.toFixed(1) + " ";
  }
  g += `<path d="${path}" fill="none" stroke="#2f7df6" stroke-width="2.5"/>`;
  const legLen = 120;
  g += `<line x1="${cx}" y1="${cy}" x2="${cx + legLen}" y2="${cy}" stroke="#9aa3b2" stroke-width="4" stroke-linecap="round"/>`;
  g += `<text x="${cx + legLen - 4}" y="${cy + 18}" fill="#6b7280" font-size="12">고정된 막대</text>`;
  const a = -thetaDeg * Math.PI / 180;
  const ex = cx + legLen * Math.cos(a), ey = cy + legLen * Math.sin(a);
  g += `<line x1="${cx}" y1="${cy}" x2="${ex.toFixed(1)}" y2="${ey.toFixed(1)}" stroke="#2f7df6" stroke-width="4" stroke-linecap="round"/>`;
  g += `<text x="${ex.toFixed(1)}" y="${(ey-10).toFixed(1)}" fill="#2f7df6" font-size="12" font-weight="bold">도어 미는 막대</text>`;
  const arcR = 42;
  const ax = cx + arcR, ay = cy;
  const bx = cx + arcR * Math.cos(a), by = cy + arcR * Math.sin(a);
  const large = thetaDeg > 180 ? 1 : 0;
  g += `<path d="M ${ax} ${ay} A ${arcR} ${arcR} 0 ${large} 0 ${bx.toFixed(1)} ${by.toFixed(1)}" fill="none" stroke="#f59e0b" stroke-width="2"/>`;
  g += `<text x="${cx + arcR + 6}" y="${cy - arcR/2}" fill="#f59e0b" font-size="13" font-weight="bold">${fmt(thetaDeg,0)}° 비틀림</text>`;
  g += `<text x="18" y="26" fill="#1f2937" font-size="13">철사 굵기 = ${fmt(d,2)} mm</text>`;
  g += `<text x="18" y="46" fill="#1f2937" font-size="13">동그라미 = ${fmt(D,2)} mm</text>`;
  svg.innerHTML = g;
}

