// ===================== 이벤트 =====================
const DEFAULTS = { material:"music", d:"1.0", diaInput:"10", n:"5", L:"20", theta:"90", dw:"40", dd:"30", dh:"10", dweight:"15", theta0:"0", fwant:"3", fricPct:"30" };
const RANGE_OF = { d:"dRange", diaInput:"diaRange", n:"nRange", L:"LRange", theta:"thetaRange", theta0:"pl0Range" };

function linkRange(numId, rangeId) {
  const num = $(numId), rng = $(rangeId);
  const onChange = () => { if (numId === "d") applyMaterial(); render(); };
  rng.addEventListener("input", () => { num.value = rng.value; onChange(); });
  num.addEventListener("input", () => { rng.value = num.value; onChange(); });
}
function syncRanges() {
  Object.entries(RANGE_OF).forEach(([numId, rangeId]) => { $(rangeId).value = $(numId).value; });
}

function bind() {
  populateMaterials();
  applyMaterial();
  $("material").addEventListener("change", () => { applyMaterial(); render(); });

  // 슬라이더 ↔ 숫자 연동
  Object.entries(RANGE_OF).forEach(([numId, rangeId]) => linkRange(numId, rangeId));

  // 슬라이더 없는 입력 (도어 치수·무게)
  ["dw","dd","dh","dweight","fricPct"].forEach(id => $(id).addEventListener("input", render));

  // 동그라미 지름 기준 토글
  $("dmode").querySelectorAll("button").forEach(b =>
    b.addEventListener("click", () => {
      diaMode = b.dataset.mode;
      $("dmode").querySelectorAll("button").forEach(x => x.classList.toggle("active", x === b));
      $("diaLabel").textContent = { mean: "가운데 지름", od: "바깥 지름", id: "안쪽 지름" }[diaMode];
      render();
    }));

  // 다리 길이: 직접 입력 ↔ 힘으로 자동
  $("legMode").querySelectorAll("button").forEach(b =>
    b.addEventListener("click", () => {
      legMode = b.dataset.mode;
      $("legMode").querySelectorAll("button").forEach(x => x.classList.toggle("active", x === b));
      $("legManual").style.display = legMode === "manual" ? "" : "none";
      $("legAuto").style.display   = legMode === "auto" ? "" : "none";
      render();
    }));
  $("fwant").addEventListener("input", render);

  // 작동 빈도 / 쇼트피닝 토글
  $("lifeMode").querySelectorAll("button").forEach(b =>
    b.addEventListener("click", () => {
      lifeMode = b.dataset.mode;
      $("lifeMode").querySelectorAll("button").forEach(x => x.classList.toggle("active", x === b));
      render();
    }));
  $("peenMode").querySelectorAll("button").forEach(b =>
    b.addEventListener("click", () => {
      peenMode = b.dataset.mode;
      $("peenMode").querySelectorAll("button").forEach(x => x.classList.toggle("active", x === b));
      render();
    }));

  // 처음으로 (기본값 복원)
  $("resetBtn").addEventListener("click", () => {
    Object.entries(DEFAULTS).forEach(([id, v]) => { $(id).value = v; });
    diaMode = "mean"; legMode = "manual"; lifeMode = "high"; peenMode = "no";
    $("dmode").querySelectorAll("button").forEach(x => x.classList.toggle("active", x.dataset.mode === "mean"));
    $("legMode").querySelectorAll("button").forEach(x => x.classList.toggle("active", x.dataset.mode === "manual"));
    $("legManual").style.display = ""; $("legAuto").style.display = "none";
    $("lifeMode").querySelectorAll("button").forEach(x => x.classList.toggle("active", x.dataset.mode === "high"));
    $("peenMode").querySelectorAll("button").forEach(x => x.classList.toggle("active", x.dataset.mode === "no"));
    $("diaLabel").textContent = "가운데 지름";
    syncRanges();
    applyMaterial();
    render();
  });

  runTests();
  render();
  startAnim();
}
bind();
</script>
</body>
</html>

