cd "C:\Users\redna\torsion-spring-simulator" && node -e "
// 핵심 로직 검증
function computeSpring(p) {
  const { E, d, D, n, L, thetaDeg } = p;
  const C = D / d;
  const kTurn = (E * Math.pow(d, 4)) / (10.8 * D * n);
  const kDeg = kTurn / 360;
  const M = kDeg * thetaDeg;
  const F = L > 0 ? M / L : 0;
  const Ki = (4 * C * C - C - 1) / (4 * C * (C - 1));
  const sigma = Ki * 32 * M / (Math.PI * Math.pow(d, 3));
  return { C, kTurn, kDeg, M, F, Ki, sigma };
}

// 자가 테스트 (보정 전 n=5 기준 — 기존과 동일해야 함)
const r = computeSpring({ E: 207000, d: 1.0, D: 10, n: 5, L: 20, thetaDeg: 90 });
console.log('k_turn:', r.kTurn.toFixed(2), '(기대 383.33)');
console.log('M:', r.M.toFixed(2), '(기대 95.83)');
console.log('C:', r.C, '(기대 10)');

// B-5 보정 적용 후 (n_eff = 5 + 2*20/(3*pi*10))
const n_eff = 5 + 2*20 / (3*Math.PI*10);
console.log('n_eff:', n_eff.toFixed(4));
const r2 = computeSpring({ E: 207000, d: 1.0, D: 10, n: n_eff, L: 20, thetaDeg: 90 });
console.log('보정 후 k_turn:', r2.kTurn.toFixed(2));
console.log('보정 후 M:', r2.M.toFixed(2));
console.log('보정 후 F:', r2.F.toFixed(3));
console.log('보정 후 sigma:', r2.sigma.toFixed(1));
"

